from pathlib import Path
import json
from html import escape as e
from urllib.parse import urlencode
R=Path(__file__).resolve().parents[1]
book=json.loads((R/'content/book.json').read_text())
d=json.loads((R/'content/collection.json').read_text()); images={x['id']:x for x in d['images']}
def image_path(id):
 return images[id].get('path',f'assets/{id}.jpg')
def fig(id):
 x=images[id]
 return f'<figure><a href="{image_path(id)}"><img src="{image_path(id)}" alt="{e(x["title"])}" loading="lazy" width="1800" height="1200"></a><figcaption>{e(x["title"])} · {e(x["date"])}. Pars from the Past, p. {e(x["page"])}. <a href="archive.html#{id}">Image record ↗</a></figcaption></figure>'
def cards(items):return '<div class="cards">'+''.join(f'<a class="card" href="{x["id"]}.html">'+(f'<img src="{image_path(x["image"])}" alt="" loading="lazy">' if x['image'] else f'<div class="type-image">{e(x["date"].split(" · ")[0])}</div>')+f'<div><span class="eyebrow">{e(x["date"])}</span><h3>{e(x["title"])}</h3><p>{e(x["intro"])}</p><span class="read">Read the story →</span></div></a>' for x in items)+'</div>'
def recent_records(group):
 records=sorted((x for x in d.get('records',[]) if group in x.get('groups',[]) and x.get('review_status')=='approved'),key=lambda x:x['date'],reverse=True)
 if not records:return '<p class="quiet">No recent records added yet. This area will hold dated contributions, results, photographs and accounts of club activities.</p>'
 return ''.join(f'<article class="club-record"><span class="eyebrow">{e(x["date"])}</span><h3>{e(x["title"])}</h3><p>{e(x["summary"])}</p><details><summary>Read the record</summary><p>{e(x["body"])}</p><p class="source">Contributor: {e(x["contributor"])} · Source: {e(x["source"])}</p></details></article>' for x in records)
def group_book_links(group):
 chapters={'juniors':[(18,'Personal experiences'),(12,'Resident professionals')],'ladies':[(8,'Women’s golf'),(10,'The women veterans'),(24,'The Una Wickham Memorial Tournament')],'ladies-nine-hole':[(8,'Women’s golf and nine-hole origins')],'men':[(7,'Men’s golf'),(19,'The Ward dynasty')],'senior-men':[(9,'Veteran men’s golf')]}
 links=''.join(f'<p><a href="book-{n:02}.html">{e(title)} · Original book →</a></p>' for n,title in chapters.get(group,[]))
 if group=='ladies-nine-hole':links+='<p><a href="book-page-106.html">Phyll Sandlant’s own account · p. 106 →</a></p>'
 if group=='juniors':links+='<p><a href="book-page-173.html">Junior championship eligibility · p. 173 →</a></p><p><a href="book-page-281.html">Juniors and the changing culture · p. 281 →</a></p>'
 return '<h3>More from Dave’s book</h3>'+links
nav=[('index.html','Home'),('subjects.html','Subjects'),('history.html','Through Time'),('course.html','The Course'),('people.html','People & Stories'),('club.html','Our Club'),('archive.html','Archive'),('search.html','Search')]
def page(file,title,body):
 body_class='source-reader' if file.startswith('book-page-') else ''
 feedback_url='https://github.com/bwucee/Tauranga-Golf-Club-Heritage/issues/new?'+urlencode({'template':'member-feedback.yml','title':'Feedback: '+title,'page':file})
 links=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==file else '')+f'>{n}</a>' for p,n in nav)
 html=f'''<!doctype html><html lang="en-NZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{e(title)} | Tauranga Golf Club Heritage</title><meta name="description" content="Explore Tauranga Golf Club’s history and continuing story through people, photographs and club records."><link rel="stylesheet" href="assets/style.css"></head><body class="{body_class}"><a class="skip" href="#main">Skip to content</a><div class="preview">WORKING PREVIEW <span>Member review edition · The book and our continuing history</span></div><header><a class="brand" href="index.html"><img class="club-logo" src="assets/club-logo.jpg" alt="Tauranga Golf Club"><span class="collection-label">HERITAGE &amp; CLUB LIFE</span></a><a class="club-link" href="https://www.taurangagolf.co.nz/">Club website ↗</a></header><nav aria-label="Heritage collection">{links}</nav><main id="main">{body}<aside class="feedback-invite"><h2>Help this collection grow.</h2><p>A correction, a name for a face, or a story to add? Your knowledge can make the record richer.</p><a href="{e(feedback_url)}">Comment on this page via GitHub ↗</a> · <a href="feedback.html">Other ways to share feedback</a></aside></main><footer><div><strong>Tauranga Golf Club</strong><p>Heritage &amp; Club Life · Building on Pars from the Past</p></div><div><a href="subjects.html">Browse by subject</a><br><a href="people-index.html">Find a person</a><br><a href="editorial-updates.html">Contributions &amp; corrections</a><br><a href="book.html">Explore Dave’s book</a><br><a href="search.html">Search the collection</a><br><a href="feedback.html">Share feedback or a memory</a><br><a href="sources.html">Sources & editorial notes</a><br><a href="https://www.taurangagolf.co.nz/history?ComeFromCat=1338">Return to the club’s History page ↗</a></div><p class="fine">Member review edition · Historical text remains open to correction. Images authorised for publication.</p></footer><script src="assets/site.js" defer></script></body></html>'''
 (R/file).write_text(html)
def heading(k,t,p):return f'<div class="page-heading"><span class="eyebrow">{k}</span><h1>{t}</h1><p class="lead">{p}</p></div>'
page('index.html','Heritage & Club Life','''<section class="hero"><div class="hero-copy"><span class="eyebrow">HERITAGE &amp; CLUB LIFE</span><h1>Our club.<br>Our continuing story.</h1><p class="lead">From the first fairways to the people playing today. Begin with a moment, a place or a part of the club, and follow what interests you.</p><a class="button" href="subjects.html">Explore by subject <span>→</span></a><a class="secondary-link" href="club.html">Find your part of the club →</a><p class="hero-note">The 2014 book, earlier sources and later contributions</p></div><figure><img src="assets/domain.jpg" alt="Two early golfers below The Elms, with the estuary behind them" width="1800" height="1137" fetchpriority="high"><figcaption>E. T. Baker &amp; H. B. Mountfort · c.1904–1913<br>A. J. Mirrielees · Pars from the Past, p. 1</figcaption></figure></section><section class="book-credit"><span class="eyebrow">BUILT ON DAVE MOWAT’S WORK</span><h2>A book that gave our history a home.</h2><p>Dave Mowat devoted years to bringing together <em>Pars from the Past</em>, published in 2014 to celebrate one hundred years of golf at Gate Pa. This collection builds on that work, preserving its source references as we add more of the club’s continuing story.</p><a href="book.html">Explore Dave’s book →</a> · <a href="about.html">About the collection</a></section><section><div class="section-head"><div><span class="eyebrow">CHOOSE YOUR WAY IN</span><h2>A little at a time.</h2></div></div><div class="explore-doors"><a href="subjects.html"><span class="eyebrow">01 · THROUGH SUBJECTS</span><h3>Find your interest</h3><p>Greenkeeping, professionals, life members, individual stories, course development and tournaments.</p><span class="read">Browse the subject index →</span></a><a href="club.html"><span class="eyebrow">02 · THROUGH PEOPLE</span><h3>Our club</h3><p>Juniors, Ladies, Ladies 9 Hole, Men and Senior Men: their stories, achievements and records.</p><span class="read">Find a club group →</span></a><a href="archive.html"><span class="eyebrow">03 · THROUGH PICTURES</span><h3>The archive</h3><p>Look closer at the photographs and documents behind the stories.</p><span class="read">Browse the archive →</span></a></div></section><section class="featured-story"><img src="assets/avenue.jpg" alt="The original first hole, The Avenue; photograph undated" loading="lazy"><div><span class="eyebrow">A STORY TO START WITH · 1914</span><h2>A new home at Gate Pa.</h2><p>Members turned exposed reserve land into a place for golf. Follow the move that shaped the club.</p><a class="read" href="gate-pa.html">Read the story →</a></div></section>''')
page('history.html','Our history',heading('THE HISTORICAL FRAMEWORK','One chapter at a time.','Start with an era. Within each chapter, follow the timeline or explore the course, people and photographs.')+'<div class="reader-tools"><a href="timeline.html">Follow the complete timeline →</a><a href="book.html">Browse the book by subject →</a></div><div class="era-list">'+''.join((f'<a class="era" href="{x["link"]}">' if x.get('link') else '<div class="era planned">')+f'<span class="year">{e(x["years"])}</span><h2>{e(x["title"])}</h2><span class="read">{e(x["status"])}</span>'+('</a>' if x.get('link') else '</div>') for x in d['eras'])+'</div><p class="source">Stories may span more than one period. This framework leads to short introductions; the book collection preserves the fuller accounts, photographs and reference pages.</p>')
page('club.html','Our club',heading('PEOPLE · PARTICIPATION · CONTINUITY','Find your part of the club.','Explore a group’s stories and records. As the collection grows, recent achievements and activities will sit alongside its earlier history.')+'<div class="group-list">'+''.join(f'<details id="{g["id"]}"><summary>{e(g["title"])}<span>Explore this group</span></summary><div class="group-body"><p>{e(g["intro"])}</p><h3>Stories in this collection</h3>'+(''.join(f'<p><a href="{a["id"]}.html">{e(a["title"])}</a><br><span class="source">{e(a["date"])}</span></p>' for a in d['articles'] if g['id'] in a.get('groups',[])) or '<p class="quiet">Material for this group has yet to be added.</p>')+('<h3>A member’s own account</h3><p><a href="jack-carter.html">Jack Carter’s golfing life →</a></p>' if g['id'] in ('juniors','men','senior-men') else '')+group_book_links(g['id'])+('<h3>Trophy records</h3><p><a href="trophies.html">Explore seven supplied trophy records →</a></p>' if g['id']=='senior-men' else '')+'<h3>Recent records</h3>'+recent_records(g['id'])+'</div></details>' for g in d['groups'])+'</div><p class="source">The group names are an initial framework and can expand with the club. Current membership, bookings and event information remain on the <a href="https://www.taurangagolf.co.nz/">main club website</a>.</p>')
page('about.html','The book and this collection',heading('ACKNOWLEDGING THE FOUNDATION','From Dave’s book to a growing collection.','An extension of the work behind Pars from the Past, with space for the club’s continuing story.')+'''<div class="prose"><h2>Years of work, brought together</h2><p>Edited by David G. S. Mowat and published in 2014, <em>Pars from the Past</em> marked one hundred years of golf on the Gate Pa links. Dave brought together research, recollections, photographs and records to create a lasting account of the club.</p><p>The book acknowledges the earlier historical work of Joan Mirrielees and Deidre Hartley, as well as the many members and contributors who helped preserve this material. This website carries those acknowledgements forward.</p><h2>A foundation we can build on</h2><p>The initial historical stories are drawn from the book, with page references retained. As more material is added, its own sources and contributors will be identified. New contributions will remain distinguishable from the book’s account.</p><h2>History and the life of the club</h2><p>The historical framework gives visitors a way through time. Club group collections will also preserve more recent achievements, activities, photographs and records, so today’s club life can become part of tomorrow’s history.</p><p>Visitors can start with a short overview and choose how far to follow a subject. The structure is in place; the detail will grow a piece at a time.</p><p class="source">Book context: Pars from the Past (2014), title page, acknowledgements, foreword and introduction, pp. 1–5.</p><a href="sources.html">Sources and editorial notes →</a></div>''')
def timeline_rows(events):
 return '<ol class="timeline">'+''.join(f'<li><span class="year">{e(year)}</span><div><h2><a href="{id}.html">{e(title)}</a></h2><p>{e(text)}</p><p class="source">Book, pp. {e(pages)} · <a href="{id}.html">Read the story →</a></p></div></li>' for year,title,text,id,pages in events)+'</ol>'
by_id={a['id']:a for a in d['articles']}
def era_events(era):
 import re
 ranges={'beginnings':(1903,1923),'interwar':(1924,1945),'postwar':(1946,1959),'sixties':(1960,1979),'eighties':(1980,1999),'modern':(2000,2014)}
 lo,hi=ranges[era]
 return [t for t in d['timeline'] if (m:=re.search(r'\d{4}',t[0])) and lo<=int(m[0])<=hi]
page('timeline.html','Timeline',heading('1903–2014','The club’s story, in order.','Choose a period to unfold its milestones. Follow any event into its story, photographs and source notes.')+'<div class="chapter-nav">'+''.join(f'<a href="#{x["id"]}">{e(x["years"])}</a>' for x in d['eras'] if x.get('link'))+'</div>'+''.join(f'<details class="timeline-era" id="{x["id"]}"'+(' open' if x['id']=='beginnings' else '')+f'><summary>{e(x["years"])} · {e(x["title"])}</summary>'+timeline_rows(era_events(x['id']))+'</details>' for x in d['eras'] if x.get('link'))+'<aside class="note"><h2>History and an imagined future</h2><p>The timeline follows dated accounts through the book’s 2014 publication. Dave’s predictions for the next century are preserved separately as an imaginative ending.</p><a href="daves-imagined-century.html">Read about the book’s ending →</a></aside>')
for era in d['eras']:
 if not era.get('link'):continue
 items=[a for a in d['articles'] if a.get('era')==era['id']]
 page(era['link'],era['title'],'<a class="back" href="history.html">← All historical chapters</a>'+heading(e(era['years']),e(era['title']),'Start with a story, or unfold the dated milestones below.')+cards(items)+'<details class="timeline-era"><summary>Follow this chapter’s timeline</summary>'+timeline_rows(era_events(era['id']))+'</details>')
def story_sections(category):
 result=''
 for era in d['eras']:
  items=[a for a in d['articles'] if a['category']==category and a.get('era')==era['id']]
  if items:result+=f'<section class="story-period"><span class="eyebrow">{e(era["years"])}</span><h2>{e(era["title"])}</h2>'+cards(items)+'</section>'
 return result
page('course.html','The Course',heading('1903–2014 · PLACES & PLAYING CONDITIONS','Finding room for golf.','From the Domain to Gate Pa, through redesign, water, trees, turf and changing facilities.')+story_sections('The Course'))
page('people.html','People & Stories',heading('PLAYERS · VOLUNTEERS · CLUB LIFE','People made it possible.','Choose a period or explore a club group. Each story keeps its source references close at hand.')+'<p><a href="jack-carter.html">Jack Carter’s own account →</a> · <a href="life-members.html">Life Members and their stories →</a></p><a href="club.html">Browse by club group →</a>'+story_sections('People & Stories'))
page('archive.html','Photographic Archive',heading('PHOTOGRAPHS & DOCUMENTS','Look closer at the record.','Select an image to open it at full size. Dates and identifications follow the book; uncertain details remain marked.')+'<aside class="note"><h2>Fresh material from the heritage folder</h2><p><a href="supplied-photographs.html">Five supplied photographs →</a> · <a href="trophies.html">Trophy records →</a> · <a href="life-members.html">Life Members →</a> · <a href="member-memories.html">Member memories →</a></p><h2>Photographs throughout the book</h2><p>The complete book collection contains 87 photographs and other substantial embedded images, grouped by chapter. These selected records below provide extra caption and dating notes.</p><a href="book-images.html">Browse all book images →</a></aside><div class="archive-grid">'+''.join(f'<article id="{x["id"]}">{fig(x["id"])}<h2>{e(x["title"])}</h2><p>{e(x["caption"])}</p><p class="source">Credit: {e(x["credit"])}<br>Source: Pars from the Past (2014), p. {e(x["page"])}.</p><p class="rights">Online reproduction: authorised by the project owner, 9 November 2026.</p></article>' for x in d['images'])+'</div>')
for x in d['articles']:
 source_links=x.get('book_pages') or [int(x['pages'].split('–')[0].split(',')[0])]
 original_reading='<p class="source-reading"><a href="book-page-'+f'{source_links[0]:03}'+'.html">Read the original book account →</a></p>'
 page(x['id']+'.html',x['title'],f'<a class="back" href="'+('course.html' if x['category']=='The Course' else 'people.html')+'">← '+x['category']+'</a>'+heading(e(x['date']),e(x['title']),e(x['intro']))+'<div class="article-layout"><article class="prose">'+''.join(f'<p>{e(p)}</p>' for p in x['paragraphs'])+original_reading+(' <p><a href="windsor-green.html">Windsor Green: the fairway conversion and water savings →</a></p>' if x['id'] in ['water-and-irrigation','greenkeepers','board-of-management','short-course'] else '')+'<div class="reader-tools">'+''.join(f'<a href="topic-{tid}.html">{e(tid.replace("-"," "))}</a>' for tid in x.get('topics',[]))+'</div>'+f'<aside class="note"><h2>Source note</h2><p>{e(x["source_note"]) if x.get("source_note") else "Adapted from Pars from the Past, edited by David G. S. Mowat (2014), pp. " + e(x["pages"]) + ". Newspaper reports are described as cited in the book; original issues have not yet been checked for this preview."}</p>{''.join(f'<p><a href="{e(src["url"])}">{e(src["title"])}</a></p>' for src in x.get('external_sources',[]))}<a href="sources.html">Editorial notes →</a></aside><div class="story-connections">{''.join(f'<a href="club.html#{g["id"]}">{e(g["title"])}</a>' for g in d['groups'] if g['id'] in x.get('groups',[]))}</div></article><aside>'+ (fig(x['image']) if x['image'] else '<div class="honours"><span class="eyebrow">EXPLORE FURTHER</span><h2>Follow the connections.</h2><p><a href="club.html">Club groups →</a></p><p><a href="timeline.html">The timeline →</a></p></div>')+'</aside></div>')
page('sources.html','Sources & editorial notes',heading('HOW THIS COLLECTION IS BUILT','The evidence behind the stories.','A working collection, with clear references and room for corrections.')+'''<div class="prose"><h2>Primary supplied source</h2><p><em>Pars from the Past: A History of the Tauranga Golf Club</em>, edited by David G. S. Mowat, published in 2014. Page numbers refer to printed book pages, which match the supplied PDF page numbers.</p><p>The source PDF remains outside this website and is not offered for download. The story introductions are newly written from the source. The separate book collection preserves its original accounts in attributed, page-by-page review transcriptions, with images and original-layout reference pages. It is not a PDF download.</p><h2>The club’s existing History page</h2><p>The <a href="https://www.taurangagolf.co.nz/history?ComeFromCat=1338">Tauranga Golf Club History page</a> was consulted on 9 November 2026 as a supporting overview. The book provides the detailed references used here.</p><h2>Dates and gaps</h2><p>1903 marks Brown’s arrival, not a claimed club foundation. The book supports 1904 as the foundation year. Its introduction explains the lack of early minute books and the use of recollections and newspaper research. Newspaper originals have not yet been independently checked for this preview.</p><p>The undated golfing-party and Avenue images are contextual material. Their inclusion does not establish a 1903–1923 date. The Domain course card also has a dating question noted by the book itself.</p><h2>Additional source for nine-hole golf</h2><p><a href="https://www.sunlive.co.nz/news/87217-a-hole-100.html">Luke Balvert, “A hole in 100”, SunLive, 15 November 2014</a>, identifies Patsy Hankins’s national role and her approach to Phyll Sandlant in 1998. The nine-hole story distinguishes this report from the book’s local account.</p><h2>Reading the original book</h2><p><a href="book.html">The complete book collection</a> retains Dave’s text and its own period context. Recollections, opinions, terminology and historical rules are not rewritten as current facts. The transcription removes running headers and stray layout characters; it has not been fully proofread. Multi-column honours and trophy reference pages retain their printed layout as images, alongside searchable text that must not be used to infer column relationships.</p><p>The last chapter explicitly includes an imagined future. Predictions are labelled at chapter and page level and do not appear in the factual timeline.</p><h2>Details still to check</h2><p>The source notes in the redesign, wartime, clubhouse and Veterans’ stories identify conflicting details within the book. They concern the lease chronology, wartime championship years, final clubhouse cost and a tournament date. These questions remain visible for members to help resolve.</p><h2>Image register</h2><p>Each <a href="archive.html">archive record</a> includes its book page, available credit, date status and reproduction authorisation. Images were extracted without generating or replacing historical detail; only web sizing and JPEG compression were applied.</p><h2>Review edition and image permission</h2><p>The project owner authorised all photographs and images for publication on 9 November 2026. Check the historical text and identifications with the club and verify the newspaper references where possible as the collection develops. This is a member review edition, shared to invite corrections and development suggestions. Historical editorial approval is not implied by publication of the preview.</p><h2>Alongside the main website</h2><p>The existing club History page can remain a short introduction, linking to this collection when ready. This separate static collection does not change bookings, membership, news or the club’s existing navigation. Any future address or hosting arrangement is still to be agreed.</p></div>''')
page('feedback.html','Feedback & contributions',heading('MEMBER REVIEW EDITION','Help put more skin on the bones.','Tell us what works, what needs correcting, and which parts of the club’s story we should develop next.')+'''<div class="prose"><h2>What would be useful?</h2><ul><li>Names, dates or places to correct, with a source if you have one.</li><li>People missing from a story or a photograph.</li><li>Ideas for the Juniors, Ladies, Ladies 9 Hole, Men and Senior Men collections.</li><li>Recent records, photographs or results to preserve.</li><li>Anything difficult to find or read on your phone or computer.</li></ul><h2>Leave a note on GitHub</h2><p><a class="button" href="https://github.com/bwucee/Tauranga-Golf-Club-Heritage/issues/new?template=member-feedback.yml">Add feedback ↗</a></p><p>A free GitHub account is needed to submit a note. You can <a href="https://github.com/bwucee/Tauranga-Golf-Club-Heritage/issues">browse the existing feedback</a> without signing in. Feedback there is public.</p><h2>Prefer to send your thoughts directly?</h2><p>Reply to the club member who shared this preview with you. Include the page title or link, your suggested change and any source or photograph you would like considered. This website does not collect messages through a form.</p><h2>Contributing material</h2><p>Please include the event date, names of people, the club group it relates to, and who supplied the material. For photographs, identify the photographer or owner where known and say whether they have agreed to online use. New submissions will be reviewed before joining the collection.</p><h2>What this preview covers</h2><p>Six historical chapters cover the story through 2014. All 25 chapters of Dave’s book, front matter and appendices are available in the book collection, alongside shorter story introductions. The imagined future in the final chapter is labelled and excluded from the historical timeline. New contributors will be credited as the collection grows.</p></div>''')
